mapper.insert:
INSERT INTO external_api_log (
  member_id, provider, endpoint, request_summary, response_status, success, error_message
)
VALUES (
  #{memberId}, #{provider}, #{endpoint}, #{requestSummary}, #{responseStatus}, #{success}, #{errorMessage}
)

mapper.select:
SELECT api_log_id, member_id, provider, endpoint, request_summary, response_status,
       success, error_message, created_at
FROM external_api_log
WHERE 1 = 1
AND member_id = #{memberId}
AND provider = #{provider}
AND success = #{success}
ORDER BY created_at DESC, api_log_id DESC
LIMIT #{limit} OFFSET #{offset}
